-- 4. Inserción de auditoría en historial_consultas
INSERT INTO isft189.historial_consultas
    (id, usuario_id, pregunta, respuesta, fecha_consulta) VALUES
    (1, 4, '¿Cual es la correlatividad de la materia Bases de Datos?',
        'Para cursar Bases de Datos I se requiere tener aprobada la cursada de Algoritmos y Estructuras de Datos.',
        '2024-08-10 10:15:00-03'),
    (2, 4, '¿Cuantas materias tiene el plan de Analista Programador?',
        'El plan vigente cuenta con 24 materias distribuidas a lo largo de 3 anos academicos.',
        '2024-08-12 11:05:00-03'),
    (3, 5, '¿Que porcentaje de asistencia necesito para mantener la regularidad?',
        'El reglamento general del estudiante establece una asistencia minima obligatoria del 75%.',
        '2024-08-13 09:40:00-03'),
    (4, 5, '¿En que meses se sustancian los examenes finales?',
        'Segun el reglamento de examenes, los turnos ordinarios se realizan en julio/agosto y noviembre/diciembre.',
        '2024-08-15 16:20:00-03'),
    (5, 6, '¿Cual es el plazo para justificar una inasistencia medica?',
        'El plazo maximo de presentacion del certificado medico es de 48 horas habiles.',
        '2024-08-18 12:30:00-03'),
    (6, 3, '¿Que correlativa se requiere para Programacion Web en Software?',
        'Para cursar Programacion Web se requiere regularidad previa en Programacion Orientada a Objetos.',
        '2024-08-20 14:10:00-03');

SELECT setval(pg_get_serial_sequence('isft189.historial_consultas', 'id'),
              (SELECT MAX(id) FROM isft189.historial_consultas));

COMMIT;

-- Consultas de validación e integración RAG (Consigna Sección D)

-- Consulta 1: Búsqueda por similitud vectorial pura (Top-3 más cercanos al vector semilla 401)
-- Representa la búsqueda semántica de la pregunta '¿Que correlativa pide Bases de Datos?'
SELECT v.id,
       v.documento_id,
       d.titulo AS titulo_documento,
       LEFT(v.contenido, 80) || '...' AS extracto,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 6))::numeric, 4) AS distancia_coseno
FROM   isft189.documentos_vectoriales v
JOIN   isft189.documentos_metadata d ON d.id = v.documento_id
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 6)
LIMIT  3;

-- Consulta 2: Búsqueda híbrida con filtro relacional estricto (documentos activos de tipo 'reglamento')
SELECT v.id,
       d.titulo,
       d.tipo_documento,
       LEFT(v.contenido, 70) || '...' AS fragmento,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 4))::numeric, 4) AS distancia_coseno
FROM   isft189.documentos_vectoriales v
JOIN   isft189.documentos_metadata d ON d.id = v.documento_id
WHERE  d.activo = TRUE
  AND  d.tipo_documento = 'reglamento'
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 4)
LIMIT  3;

-- Consulta 3: Búsqueda híbrida con filtro sobre JSONB estructurado (carrera específica en metadata)
SELECT v.id,
       v.metadata->>'carrera' AS carrera_metadata,
       v.metadata->>'materia' AS materia,
       LEFT(v.contenido, 80) AS contenido,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 6))::numeric, 4) AS distancia
FROM   isft189.documentos_vectoriales v
WHERE  v.metadata @> '{"carrera": "Analista Programador Universitario"}'
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 6)
LIMIT  3;

-- Consulta 4: Auditoría cruzada - Historial de consultas con usuario y conteo de interacciones
SELECT u.nombre,
       u.rol,
       COUNT(h.id) AS total_consultas,
       MAX(h.fecha_consulta) AS ultima_consulta
FROM   isft189.usuarios u
LEFT JOIN isft189.historial_consultas h ON h.usuario_id = u.id
GROUP  BY u.id, u.nombre, u.rol
ORDER  BY total_consultas DESC, u.nombre;
